"""Credential vault — Fernet-encrypted secrets with platform-aware master key.

Master key lookup order (first hit wins):

1. ``AGENT_ML_MANAGER_VAULT_KEY`` env var (base64 Fernet key) — CI / tests / overrides.
2. macOS Keychain (service ``agent-ml-manager``, account ``vault-master-key``) — only on darwin.
3. Keyfile at ``<manager_home>/secrets/master.key`` — Linux / non-macOS hosts.

On non-macOS hosts the keyfile is auto-created on first use if missing
(server-side automation can't prompt for ``vault-init``). The new key is
logged at WARNING level so operators know to back it up.

Encrypted credential files live under ``<manager_home>/secrets/servers/``.
"""

from __future__ import annotations

import json
import logging
import os
import secrets
import subprocess
import sys
from pathlib import Path

import base64
from cryptography.fernet import Fernet, InvalidToken

from .. import paths as _paths

logger = logging.getLogger(__name__)

_KEYCHAIN_SERVICE = "agent-ml-manager"
_KEYCHAIN_ACCOUNT = "vault-master-key"


def _is_macos() -> bool:
    return sys.platform == "darwin"


def _keyfile_path() -> Path:
    return _paths.manager_home() / "secrets" / "master.key"


def _keyfile_read() -> str | None:
    p = _keyfile_path()
    if not p.exists():
        return None
    try:
        return p.read_text().strip() or None
    except OSError:
        return None


def _keyfile_write(key_b64: str) -> None:
    p = _keyfile_path()
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(key_b64)
    p.chmod(0o600)


class VaultError(Exception):
    pass


class VaultMissingKey(VaultError):
    pass


def _secrets_dir() -> Path:
    return _paths.manager_home() / "secrets" / "servers"


def _keychain_read() -> str | None:
    try:
        result = subprocess.run(
            ["security", "find-generic-password",
             "-s", _KEYCHAIN_SERVICE, "-a", _KEYCHAIN_ACCOUNT, "-w"],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0:
            return result.stdout.strip()
    except (subprocess.SubprocessError, OSError):
        pass
    return None


def _keychain_write(key_b64: str, *, force: bool = False) -> None:
    if force:
        subprocess.run(
            ["security", "delete-generic-password",
             "-s", _KEYCHAIN_SERVICE, "-a", _KEYCHAIN_ACCOUNT],
            capture_output=True, timeout=10,
        )
    subprocess.run(
        ["security", "add-generic-password",
         "-s", _KEYCHAIN_SERVICE, "-a", _KEYCHAIN_ACCOUNT, "-w", key_b64],
        capture_output=True, text=True, timeout=10, check=True,
    )


def load_master_key() -> bytes:
    """Load master key from env var, Keychain (macOS), or keyfile.

    Returns the raw Fernet key (base64-encoded 32 bytes).
    On non-macOS hosts a keyfile is auto-created if missing — server-side
    automation can't run ``vault-init`` interactively, and a brand-new
    install has no ciphertext yet, so generating one is safe.
    Raises VaultMissingKey only on macOS hosts that have neither env var
    nor a Keychain entry.
    """
    env_key = os.environ.get("AGENT_ML_MANAGER_VAULT_KEY")
    if env_key:
        return env_key.encode()

    if _is_macos():
        kc_key = _keychain_read()
        if kc_key:
            return kc_key.encode()
        # macOS: don't auto-init — operator is expected to run vault-init.
        raise VaultMissingKey(
            "No vault master key found. Run `agent-ml-manager vault-init` "
            "or set AGENT_ML_MANAGER_VAULT_KEY."
        )

    file_key = _keyfile_read()
    if file_key:
        return file_key.encode()

    new_key = Fernet.generate_key().decode()
    _keyfile_write(new_key)
    logger.warning(
        "vault: auto-created master key at %s — "
        "back this up; losing it makes all stored credentials unrecoverable",
        _keyfile_path(),
    )
    return new_key.encode()


def init_master_key(*, force: bool = False) -> str:
    """Generate a new Fernet key and store in Keychain (macOS) or keyfile.

    Returns the key as a base64 string (for the user to back up).
    Raises VaultError if a key already exists and force=False.
    """
    if _is_macos():
        if not force:
            existing = _keychain_read()
            if existing:
                raise VaultError(
                    "Vault master key already exists in Keychain. "
                    "Use force=True to overwrite."
                )
        key_str = Fernet.generate_key().decode()
        _keychain_write(key_str, force=force)
        return key_str

    if not force:
        existing = _keyfile_read()
        if existing:
            raise VaultError(
                f"Vault master key already exists at {_keyfile_path()}. "
                "Use force=True to overwrite."
            )
    key_str = Fernet.generate_key().decode()
    _keyfile_write(key_str)
    return key_str


def _get_fernet() -> Fernet:
    return Fernet(load_master_key())


def encrypt(plaintext: dict) -> bytes:
    """dict -> JSON -> Fernet ciphertext bytes."""
    data = json.dumps(plaintext, ensure_ascii=False).encode()
    return _get_fernet().encrypt(data)


def decrypt(ciphertext: bytes) -> dict:
    """Fernet ciphertext -> JSON -> dict. Raises VaultError on failure."""
    try:
        raw = _get_fernet().decrypt(ciphertext)
        return json.loads(raw)
    except (InvalidToken, json.JSONDecodeError) as exc:
        raise VaultError(f"Failed to decrypt credentials: {exc}") from exc


def store_credentials(server_id: str, creds: dict) -> Path:
    """Encrypt and write credentials to secrets/servers/<server_id>.enc."""
    d = _secrets_dir()
    d.mkdir(parents=True, exist_ok=True)
    path = d / f"{server_id}.enc"
    path.write_bytes(encrypt(creds))
    path.chmod(0o600)
    return path


def load_credentials(server_id: str) -> dict:
    """Read and decrypt credentials for a server."""
    path = _secrets_dir() / f"{server_id}.enc"
    if not path.exists():
        raise VaultError(f"No credentials found for server {server_id!r}")
    return decrypt(path.read_bytes())


def delete_credentials(server_id: str) -> bool:
    """Delete credential file. Returns True if deleted, False if not found."""
    path = _secrets_dir() / f"{server_id}.enc"
    if not path.exists():
        return False
    path.unlink()
    return True


# ---------------------------------------------------------------------------
# Application API keys (Anthropic, OpenAI, HF, …)
# ---------------------------------------------------------------------------

def _app_keys_dir() -> Path:
    return _paths.manager_home() / "secrets" / "app_keys"


def store_app_key(key_id: str, data: dict) -> Path:
    """Encrypt and write an application API key."""
    d = _app_keys_dir()
    d.mkdir(parents=True, exist_ok=True)
    path = d / f"{key_id}.enc"
    path.write_bytes(encrypt(data))
    path.chmod(0o600)
    return path


def load_app_key(key_id: str) -> dict:
    """Read and decrypt an application API key."""
    path = _app_keys_dir() / f"{key_id}.enc"
    if not path.exists():
        raise VaultError(f"No app key found for {key_id!r}")
    return decrypt(path.read_bytes())


def delete_app_key(key_id: str) -> bool:
    """Delete an app key file. Returns True if deleted, False if not found."""
    path = _app_keys_dir() / f"{key_id}.enc"
    if not path.exists():
        return False
    path.unlink()
    return True


def list_app_keys() -> list[dict]:
    """List all stored app keys (metadata only — no secret values)."""
    d = _app_keys_dir()
    if not d.exists():
        return []
    results = []
    for p in sorted(d.glob("*.enc")):
        key_id = p.stem
        try:
            data = decrypt(p.read_bytes())
            results.append({
                "key_id": key_id,
                "provider": data.get("provider", ""),
                "purpose": data.get("purpose", ""),
                "created_at": data.get("created_at", ""),
            })
        except VaultError:
            results.append({"key_id": key_id, "provider": "?", "purpose": "decrypt failed"})
    return results

"""Symmetric encryption for secrets (Admin Tokens, API Keys).

Uses Fernet (AES-128-CBC + HMAC-SHA256) with a key derived from the machine ID.
Goal: prevent plain-text exposure if files are read by the Agent or leaked —
this is NOT a substitute for OS-level access control.
"""

from __future__ import annotations

import base64
import hashlib
import uuid
from pathlib import Path

from cryptography.fernet import Fernet, InvalidToken

# Deterministic salt — changing this invalidates all stored secrets.
_SALT = b"agent-ml-research-tum-v1"


def _derive_key() -> bytes:
    """Derive a Fernet key from the machine's MAC address + salt."""
    machine_id = str(uuid.getnode()).encode()
    raw = hashlib.pbkdf2_hmac("sha256", machine_id, _SALT, iterations=100_000, dklen=32)
    return base64.urlsafe_b64encode(raw)


_fernet: Fernet | None = None


def _get_fernet() -> Fernet:
    global _fernet
    if _fernet is None:
        _fernet = Fernet(_derive_key())
    return _fernet


def encrypt(plaintext: str) -> str:
    """Encrypt a string, return URL-safe base64 ciphertext."""
    return _get_fernet().encrypt(plaintext.encode()).decode()


def decrypt(ciphertext: str) -> str | None:
    """Decrypt ciphertext. Returns None if invalid/corrupted."""
    try:
        return _get_fernet().decrypt(ciphertext.encode()).decode()
    except (InvalidToken, Exception):
        return None


# --- File-level helpers (for admin token / API keys) ---

def save_secret(path: Path, plaintext: str) -> None:
    """Encrypt and write a secret to a file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(encrypt(plaintext))


def load_secret(path: Path) -> str | None:
    """Read and decrypt a secret from a file. Returns None if missing/invalid."""
    if not path.exists():
        return None
    ciphertext = path.read_text().strip()
    if not ciphertext:
        return None
    return decrypt(ciphertext)
